"""Chapter 30 -- Ergodic theory and invariant measures.

A five-hundred-year control run and a hundred-member ensemble both claim to
state "the climate". This chapter asks what object they are estimating, when
they estimate the same one, and how long each has to be.

Part VIII of *An Interactive Chaos and Predictability Textbook*.

Numerics come from `chaoslib`; this file holds the exposition and the figures.
The experiments are precomputed by `scripts/generate_ch30_data.py`.

To edit:   marimo edit notebooks/ch30_ergodic-theory.py
To export: make nb-one NB=ch30_ergodic-theory
"""

import marimo

__generated_with = "0.23.9"
app = marimo.App(width="full", app_title="Chapter 30: Ergodic Theory")


@app.cell
async def imports():
    import marimo as mo

    import sys

    if sys.platform == "emscripten":
        import micropip

        await micropip.install(
            str(
                mo.notebook_location()
                / "public"
                / "chaoslib-0.1.0-py3-none-any.whl"
            )
        )
    else:
        sys.path.insert(0, str(mo.notebook_dir().parent))

    import numpy as np
    import matplotlib.pyplot as plt

    from chaoslib import earlywarning, ergodic, plotting

    C_CONTEXT = plotting.mpl_colour(plotting.C_CONTEXT)
    C_TRUTH = plotting.C_TRUTH
    C_PERT = plotting.C_PERT
    C_SPREAD = plotting.C_SPREAD
