# ===========================================================================
# Section 1
# ===========================================================================
@app.cell(hide_code=True)
def s1_md(mo):
    mo.md(
        r"""
    ## 1 · The object: climate is a measure, not a trajectory

    Run Lorenz 63 once for 60,000 time units — about 820 years at the book's five days
    per unit — and record the state every time unit. Separately, start 4,000 trajectories
    from scattered initial conditions, integrate each for 300 time units so that where it
    started is forgotten, and read all 4,000 states **at one instant**.

    The first is a climatology from a control run. The second is a climate ensemble.
    They are different experiments answering the same question, and the figure below is
    the answer: *the same distribution*.

    That distribution is the invariant measure. It is the object both estimators are
    estimating, and neither the long run nor the ensemble is closer to being "the
    climate" than the other — they are two samplers of one measure.
    """
    )
    return


@app.cell(hide_code=True)
def s1_fig(
    BOX_OCCUPIED,
    BOX_SIDES,
    BOX_USABLE,
    CONTROL_OCCUPIED,
    CONTROL_USABLE,
    C_BG,
    C_CONTEXT,
    C_MEAN,
    C_PERT,
    C_TRUTH,
    EDGES_Z,
    HIST_LONG_Z,
    HIST_SNAP_Z,
    REFERENCE_X,
    REFERENCE_Z,
    SNAPSHOT_X,
    SNAPSHOT_Z,
    finish_mpl,
    mpl_panels,
    np,
):
    _fig, _ax = mpl_panels(
        3,
        titles=(
            "one long run vs one ensemble",
            "the ensemble, at a single instant",
            "box counting: a measure with no density",
        ),
        height=3.5,
    )

    _edges = np.asarray(EDGES_Z)
    _centre = 0.5 * (_edges[1:] + _edges[:-1])
    _ax[0].step(_centre, np.asarray(HIST_LONG_Z), where="mid", color=C_TRUTH,
                linewidth=1.8, label="one run, 60,000 TU")
    _ax[0].step(_centre, np.asarray(HIST_SNAP_Z), where="mid", color=C_PERT,
                linewidth=1.4, linestyle="--", label="4,000 members, one instant")
    _ax[0].set_xlabel("$z$")
    _ax[0].set_ylabel("probability density")
    _ax[0].legend(fontsize=7, frameon=False, loc="upper right")

    _ax[1].scatter(np.asarray(REFERENCE_X), np.asarray(REFERENCE_Z), s=1.2,
                   color=C_CONTEXT, linewidths=0, label="the long run")
    _ax[1].scatter(np.asarray(SNAPSHOT_X), np.asarray(SNAPSHOT_Z), s=4.0,
                   color=C_MEAN, alpha=0.8, linewidths=0, label="the ensemble")
    _ax[1].set_xlabel("$x$")
    _ax[1].set_ylabel("$z$")
    _ax[1].legend(fontsize=7, frameon=False, loc="lower right", markerscale=3.0)

    _sides = np.asarray(BOX_SIDES)
    _box = np.asarray(BOX_OCCUPIED)
    _ctrl = np.asarray(CONTROL_OCCUPIED)
    _box_ok = np.asarray(BOX_USABLE) > 0
    _ctrl_ok = np.asarray(CONTROL_USABLE) > 0
    # filled = used in the fit; hollow = too few points per box to be geometry
    _ax[2].loglog(_sides, _ctrl, "--", color=C_BG, linewidth=1.3,
                  label="uniform control")
    _ax[2].loglog(_sides, _ctrl, "o", markerfacecolor="white", color=C_BG,
                  markersize=5)
    _ax[2].loglog(_sides[_ctrl_ok], _ctrl[_ctrl_ok], "o", color=C_BG, markersize=5)
    _ax[2].loglog(_sides, _box, "--", color=C_TRUTH, linewidth=1.3, label="Lorenz 63")
    _ax[2].loglog(_sides, _box, "o", markerfacecolor="white", color=C_TRUTH,
                  markersize=5)
    _ax[2].loglog(_sides[_box_ok], _box[_box_ok], "o", color=C_TRUTH, markersize=5)
    _ref = _sides.astype(float) ** 3
    _ax[2].loglog(_sides, _ref * _ctrl[0] / _ref[0], ":", color=C_BG, linewidth=1.0)
    _ax[2].loglog(_sides, _sides.astype(float) ** 2 * _box[0] / _sides[0] ** 2, ":",
                  color=C_TRUTH, linewidth=1.0)
    _ax[2].annotate("slope 3", (_sides[-2], _ref[-2] * _ctrl[0] / _ref[0] * 0.35),
                    fontsize=7, color=C_BG)
    _ax[2].annotate("slope 2", (_sides[-2], _sides[-2] ** 2 * _box[0] / _sides[0] ** 2
                                * 2.2), fontsize=7, color=C_TRUTH)
    _ax[2].set_xlabel("boxes per side")
    _ax[2].set_ylabel("occupied boxes")
    _ax[2].legend(fontsize=7, frameon=False, loc="upper left")
    _ax[2].annotate("hollow: too few points\nper box to be geometry",
                    xy=(0.97, 0.06), xycoords="axes fraction", fontsize=6.5,
                    color="#6b6580", ha="right", va="bottom")

    finish_mpl(
        _fig,
        "Two estimators of one measure — and the measure has no density",
    )
    return


@app.cell(hide_code=True)
def s1_note(
    BOX_DIMENSION,
    BOX_POINTS,
    CONTROL_DIMENSION,
    D_KY,
    MEAN_LONG_Z,
    MEAN_SNAP_Z,
    MIN_PER_BOX,
    SPECTRUM_SUM,
    SPREAD_Z,
    TRACE,
    W1_GAUSSIAN,
    W1_X,
    W1_Z,
    mo,
):
    mo.md(
        rf"""
    **How close is "the same distribution"?** The 1-Wasserstein distance — the work
    needed to move one distribution onto the other, in the units of the variable itself
    — is **{W1_Z:.3f}** for $z$ and **{W1_X:.3f}** for $x$, against a spread of
    {SPREAD_Z:.2f} in $z$. That is {100.0 * W1_Z / SPREAD_Z:.1f} % of the width of the
    distribution. The means agree to {abs(MEAN_LONG_Z - MEAN_SNAP_Z):.3f}.

    The control makes that readable: a Gaussian with *exactly the same mean and standard
    deviation* as the run sits $W_1 = {W1_GAUSSIAN:.3f}$ away, some
    {W1_GAUSSIAN / W1_Z:.0f} times further. The two estimators agree far more closely
    than "same mean, same variance" would buy.

    **Why $W_1$ and not a relative entropy.** $D(p\|q)$ needs densities, and on an
    attractor there are none. Two finite samples of a singular measure generically have
    disjoint support, so the relative entropy between them is infinite and any
    histogram-based estimate of it reports the bin width rather than the measure.

    ---

    **The measure has no density, and that is not a technicality.** Count how many boxes
    of side $h$ the trajectory ever visits. For a measure with a density the answer
    scales as $h^{{-3}}$ — it fills the space it lives in. Measured on
    {BOX_POINTS:,.0f} states of Lorenz 63, the count scales as $h^{{-{BOX_DIMENSION:.2f}}}$,
    while a uniform sample of the same size put through the same estimator returns
    $h^{{-{CONTROL_DIMENSION:.4f}}}$ — exactly 3, which is what validates the method.
    (Box counting is biased *low* at finite sample, because the rarely-visited boxes go
    unseen; boxes holding fewer than {MIN_PER_BOX:.0f} points on average are excluded
    from the fit for that reason, and the measured {BOX_DIMENSION:.2f} should be read
    against the $D_{{KY}} = {D_KY:.3f}$ that the Lyapunov spectrum gives independently —
    chapter 8.)

    The spectrum's own check: the three exponents sum to ${SPECTRUM_SUM:.5f}$ against an
    exact $\operatorname{{tr}}\mathbf{{J}} = {TRACE:.5f}$, which holds for every state
    and therefore for every average over them.

    So the invariant measure assigns probability one to a set of **zero volume**. It is
    *singular*: there is no function $p(x)$ with $\nu(\mathrm{{d}}x) = p(x)\,\mathrm{{d}}x$.
    Every "PDF of the climate" ever plotted — including the left panel above — is a
    coarse-grained object, and the coarse-graining is a choice made by whoever chose the
    bins. Probabilities of *sets* converge; densities do not exist to converge to.
    """
    )
    return


# ===========================================================================
# Section 2
# ===========================================================================
@app.cell(hide_code=True)
def s2_md(mo):
    mo.md(
        r"""
    ## 2 · Birkhoff gives no rate, and the rate is what you need

    The ergodic theorem says $\bar A_T \to \langle A\rangle_\nu$. It does not say when,
    and "when" is the only part a modeller can act on.

    The standard answer is the Monte Carlo law with a correlation time in place of the
    sample size. If the record decorrelates over $\tau_{\rm int}$, then a run of length
    $T$ is worth $T/\tau_{\rm int}$ independent draws and

    $$
    \operatorname{var}(\bar A_T)
      = \frac{\tau_{\rm int}\operatorname{var}(A)}{T},
    \qquad
    \tau_{\rm int} = \int_{-\infty}^{\infty}\rho(s)\,\mathrm{d}s ,
    $$

    so the error falls like $T^{-1/2}$ and halving it costs four times the integration.

    **Test it the honest way.** Rather than estimating $\tau_{\rm int}$ from the
    autocorrelation function and trusting the formula, split the run into blocks of
    length $T$ and measure the variance across block means directly. Dividing out gives
    an effective correlation time *implied by the measurement itself*,

    $$
    \tau_{\rm eff}(T) = \frac{T\operatorname{var}(\bar A_T)}{\operatorname{var}(A)} ,
    $$

    which should flatten at $\tau_{\rm int}$ once $T$ exceeds it. Three observables of
    **the same trajectory** are below: $x$, $z$, and $x^2$.
    """
    )
    return


@app.cell(hide_code=True)
def s2_fig(
    ACF_LAG,
    ACF_X,
    ACF_X2,
    ACF_Z,
    BATCH_TAU_X,
    BATCH_TAU_X2,
    BATCH_TAU_Z,
    BATCH_WINDOW_X,
    C_MEAN,
    C_PERT,
    C_SPREAD,
    C_TRUTH,
    MEAN_Z,
    RUNNING_TIME,
    RUNNING_X,
    RUNNING_Z,
    TAU_INT_X,
    TAU_INT_X2,
    TAU_INT_Z,
    finish_mpl,
    mpl_panels,
    np,
):
    _fig, _ax = mpl_panels(
        3,
        titles=(
            "autocorrelation: $z$ oscillates, $x$ does not",
            r"$\tau_{\rm eff}$ implied by the measurement",
            "the running time average",
        ),
        height=3.5,
    )

    _lag = np.asarray(ACF_LAG)
    for _series, _colour, _label in (
        (ACF_X, C_TRUTH, "$x$"),
        (ACF_Z, C_PERT, "$z$"),
        (ACF_X2, C_MEAN, "$x^2$"),
    ):
        _ax[0].plot(_lag, np.asarray(_series), color=_colour, linewidth=1.5,
                    label=_label)
    _ax[0].axhline(0.0, color="#9a93b5", linewidth=0.8)
    _ax[0].set_xlabel("lag (time units)")
    _ax[0].set_ylabel(r"$\rho$")
    _ax[0].legend(fontsize=8, frameon=False)

    _window = np.asarray(BATCH_WINDOW_X)
    for _tau, _tint, _colour, _label in (
        (BATCH_TAU_X, TAU_INT_X, C_TRUTH, "$x$"),
        (BATCH_TAU_Z, TAU_INT_Z, C_PERT, "$z$"),
        (BATCH_TAU_X2, TAU_INT_X2, C_MEAN, "$x^2$"),
    ):
        _ax[1].loglog(_window, np.asarray(_tau), "o-", color=_colour, markersize=3,
                      linewidth=1.4, label=_label)
        _ax[1].axhline(_tint, color=_colour, linewidth=0.9, linestyle=":")
    _ax[1].set_xlabel("averaging window $T$ (time units)")
    _ax[1].set_ylabel(r"$\tau_{\rm eff}(T)$")
    _ax[1].legend(fontsize=8, frameon=False, loc="lower left")
    _ax[1].annotate(
        "dotted: the standard\nautocorrelation estimate",
        xy=(0.97, 0.06), xycoords="axes fraction", fontsize=7,
        color="#6b6580", ha="right", va="bottom",
    )

    _time = np.asarray(RUNNING_TIME)
    _ax[2].plot(_time, np.asarray(RUNNING_Z) - MEAN_Z, color=C_PERT, linewidth=1.2,
                label=r"$\bar z_T - \langle z\rangle$")
    _ax[2].plot(_time, np.asarray(RUNNING_X), color=C_TRUTH, linewidth=1.2,
                label=r"$\bar x_T$   (exact value 0)")
    _ax[2].axhline(0.0, color=C_SPREAD, linewidth=0.9, linestyle="--")
    _ax[2].set_xscale("log")
    _ax[2].set_xlabel("run length (time units)")
    _ax[2].set_ylabel("error of the time average")
    _ax[2].set_ylim(-3.0, 3.0)
    _ax[2].set_xlim(1.0, _time[-1])
    _ax[2].legend(fontsize=8, frameon=False, loc="upper right")

    finish_mpl(_fig, "Three observables of one trajectory, converging at three rates")
    return


@app.cell(hide_code=True)
def s2_note(
    LAW_EXPONENT_X,
    LAW_EXPONENT_X2,
    LAW_EXPONENT_Z,
    TAU_INT_X,
    TAU_INT_X2,
    TAU_INT_Z,
    TAU_PLATEAU_X,
    TAU_PLATEAU_X2,
    TAU_PLATEAU_Z,
    mo,
):
    _rows = (
        ("$x$", TAU_INT_X, TAU_PLATEAU_X, LAW_EXPONENT_X),
        ("$z$", TAU_INT_Z, TAU_PLATEAU_Z, LAW_EXPONENT_Z),
        ("$x^2$", TAU_INT_X2, TAU_PLATEAU_X2, LAW_EXPONENT_X2),
    )
    _table = (chr(10) + "    ").join(
        f"| {_name} | {_naive:.4f} | {_measured:.4f} | "
        f"{_naive / _measured:.0f}× | $T^{{{_slope:.2f}}}$ |"
        for _name, _naive, _measured, _slope in _rows
    )
    mo.md(
        rf"""
    | observable | $\tau_{{\rm int}}$, standard estimate | $\tau_{{\rm eff}}$, measured | overestimate | $\operatorname{{var}}(\bar A_T)$ |
    |---|---|---|---|---|
    {_table}

    **For $x$ the textbook recipe is exactly right.** The autocorrelation decays
    monotonically, $\tau_{{\rm eff}}$ climbs and flattens at
    {TAU_PLATEAU_X:.3f} time units against the {TAU_INT_X:.3f} the autocorrelation
    integral predicts — {100.0 * abs(TAU_PLATEAU_X / TAU_INT_X - 1.0):.0f} % apart — and
    the variance falls like $T^{{{LAW_EXPONENT_X:.2f}}}$, the Monte Carlo law.

    **For $z$ it is wrong by a factor of {TAU_INT_Z / TAU_PLATEAU_Z:.0f}, and in the
    dangerous direction.** $z$ oscillates: its autocorrelation crosses zero at 0.2 time
    units and swings negative. The standard rule truncates the sum at that first
    crossing — the *initial positive sequence*, adopted precisely because the long-lag
    correlations are too noisy to sum — and so discards every negative lobe. Those lobes
    are what cancel the variance. The error bar that results is
    {(TAU_INT_Z / TAU_PLATEAU_Z) ** 0.5:.1f} times too wide, and the variance falls
    faster than Monte Carlo, like $T^{{{LAW_EXPONENT_Z:.2f}}}$.

    **This is not a numerical curiosity.** It has an exact cause, and the next cell is it.
    """
    )
    return


@app.cell(hide_code=True)
def s2_identity(mo):
    mo.md(
        r"""
    ### Why some averages converge faster: exact identities

    For **any** bounded function $B(x)$ of the state, the time average of its derivative
    is a pure boundary term,

    $$
    \frac{1}{T}\int_0^T \dot B\,\mathrm{d}t = \frac{B(T) - B(0)}{T},
    $$

    which falls like $T^{-1}$ with a numerator bounded by the size of the attractor.
    No ergodicity is used, no mixing, no Monte Carlo. Applying it to $x^2/2$, $z$,
    $z^2/2$ and $y^2/2$ in Lorenz 63 gives four identities that the invariant measure
    satisfies **exactly**:

    $$
    \langle xy\rangle = \langle x^2\rangle, \qquad
    \langle xy\rangle = \beta\langle z\rangle, \qquad
    \langle xyz\rangle = \beta\langle z^2\rangle, \qquad
    \rho\langle xy\rangle = \langle y^2\rangle + \langle xyz\rangle .
    $$

    The first two say that $\langle z \rangle$, $\langle x^2\rangle$ and $\langle
    xy\rangle$ are the *same measurement*. And because each differs from a total
    derivative only by a constant, its fluctuations are boundary-dominated over a wide
    range of window lengths — which is the $T^{-1}$ behaviour the table above measured
    and attributed to "negative lobes". The lobes are the symptom; this is the cause.

    Two uses follow, and the second is the one worth taking away.
    """
    )
    return


@app.cell(hide_code=True)
def s2_identity_table(
    IDENTITY_FINITE_X2,
    IDENTITY_LIMIT_Z,
    IDENTITY_MEAN_X,
    IDENTITY_MEAN_X2B,
    IDENTITY_MEAN_Z,
    IDENTITY_SPAN,
    mo,
    np,
):
    def _sci(value, digits=1):
        """Render a float as LaTeX scientific notation, not Python's `1.2e-04`."""
        _mantissa, _exponent = f"{value:.{digits}e}".split("e")
        return rf"{_mantissa}\times 10^{{{int(_exponent)}}}"

    _span = np.asarray(IDENTITY_SPAN)
    _finite = np.asarray(IDENTITY_FINITE_X2)
    _limit = np.asarray(IDENTITY_LIMIT_Z)
    _mx = np.asarray(IDENTITY_MEAN_X)
    _mz = np.asarray(IDENTITY_MEAN_Z)
    _mx2 = np.asarray(IDENTITY_MEAN_X2B)
    _table = (chr(10) + "    ").join(
        f"| {_s:,.0f} | ${_sci(_f)}$ | {_l:+.4f} | {_a:.4f} | {_b:.4f} | {_m:+.4f} |"
        for _s, _f, _l, _a, _b, _m in zip(_span, _finite, _limit, _mz, _mx2, _mx)
    )
    mo.md(
        rf"""
    | $T$ (TU) | identity **with** boundary | identity **without** | $\bar z_T$ | $\overline{{x^2}}_T/\beta$ | $\bar x_T$ |
    |---|---|---|---|---|---|
    {_table}

    **Column 2 is a test of the integrator.** With its boundary term the identity holds
    at every window, exactly — it closes to ${_sci(np.abs(_finite).max())}$ against terms of
    order 60, and it does not improve as the run lengthens because there is nothing to
    converge: it was never an approximation.

    **Column 3 is a convergence diagnostic that needs no reference run.** Drop the
    boundary term and the identity becomes a claim about the *climate*, which only a
    long enough run satisfies. It falls from ${_limit[0]:+.3f}$ at
    $T = {_span[0]:,.0f}$ to ${_limit[-1]:+.4f}$ at $T = {_span[-1]:,.0f}$. Columns 4 and
    5 are the same statement in the form a modeller would use: two quantities that
    **must** be equal, computed from one run, agreeing to
    {abs(_mz[-1] - _mx2[-1]):.4f} at the end and
    {abs(_mz[0] - _mx2[0]):.4f} at the start. A control run can be interrogated about
    its own convergence without ever being compared to anything.

    **And column 6 is the warning.** $\langle x\rangle = 0$ *exactly*, by the symmetry
    $(x, y, z) \to (-x, -y, z)$ that leaves the equations unchanged. It is the one number
    here known in advance — and it is the slowest of all of them to arrive, still
    ${_mx[4]:+.3f}$ after {_span[4]:,.0f} time units. **The quantity whose answer we know
    is the one the model is worst at telling us**, which is exactly why it, and not the
    well-behaved $\bar z$, is the honest test of whether a run is long enough.
    """
    )
    return


@app.cell(hide_code=True)
def s2_controls(mo):
    observable = mo.ui.dropdown(
        options={"x  (slow, oscillation-free)": "X",
                 "z  (fast, oscillatory)": "Z",
                 "x²  (fastest)": "X2"},
        value="x  (slow, oscillation-free)",
        label="observable",
    )
    accuracy = mo.ui.slider(
        start=0.01, stop=1.0, step=0.01, value=0.05,
        label="target standard error", show_value=True,
    )
    mo.md(
        f"""
    ### How long a run does that make?

    {observable} &nbsp;&nbsp; {accuracy}
    """
    )
    return accuracy, observable


@app.cell(hide_code=True)
def s2_out(
    DAYS_PER_TU,
    TAU_INT_X,
    TAU_INT_X2,
    TAU_INT_Z,
    TAU_PLATEAU_X,
    TAU_PLATEAU_X2,
    TAU_PLATEAU_Z,
    VAR_X,
    VAR_X2,
    VAR_Z,
    accuracy,
    ergodic,
    mo,
    observable,
):
    _table = {
        "X": (VAR_X, TAU_PLATEAU_X, TAU_INT_X, r"\langle x\rangle"),
        "Z": (VAR_Z, TAU_PLATEAU_Z, TAU_INT_Z, r"\langle z\rangle"),
        "X2": (VAR_X2, TAU_PLATEAU_X2, TAU_INT_X2, r"\langle x^2\rangle"),
    }
    _var, _tau, _naive_tau, _symbol = _table[observable.value]
    _target = float(accuracy.value)
    _need = _tau * _var / _target**2
    _need_naive = _naive_tau * _var / _target**2
    _error_1000 = ergodic.sampling_error(_var, _tau, 1000.0)
    mo.md(
        rf"""
    To pin ${_symbol}$ to $\pm{_target:.2f}$ takes **{_need:,.0f} time units** —
    about {_need * DAYS_PER_TU / 365.0:,.0f} years at five days per unit. The standard
    autocorrelation recipe would have demanded {_need_naive:,.0f}
    ({_need_naive / _need:.0f}× as much).

    A 1,000 time-unit run gives $\pm{_error_1000:.3f}$ on this observable.

    Every number here is $\tau\operatorname{{var}}(A)/\varepsilon^2$ — no fitting, and
    the only input that differs between the three observables is $\tau$. Switch between
    them at a fixed target: $\langle x\rangle$ and $\langle z\rangle$ have almost the
    same variance and differ in required run length by a factor of
    {(TAU_PLATEAU_X * VAR_X) / (TAU_PLATEAU_Z * VAR_Z):.0f}.
    """
    )
    return


# ===========================================================================
# Section 3
# ===========================================================================
@app.cell(hide_code=True)
def s3_md(mo):
    mo.md(
        r"""
    ## 3 · Ergodicity is not chaos — and chaos is the worse sampler

    The two words travel together and mean different things. **Ergodic** says one
    trajectory eventually visits everywhere in proportion to the measure. **Chaotic**
    says nearby trajectories separate exponentially. Neither implies the other, and the
    cleanest way to see it is a system that is perfectly ergodic and perfectly
    predictable at once.

    Take the circle rotation $x_{k+1} = x_k + \alpha \pmod 1$ with $\alpha$ irrational.
    Its Lyapunov exponent is exactly zero — two nearby points stay exactly as far apart
    for ever — and yet **every** orbit equidistributes on $[0,1)$. It is not merely
    ergodic but *uniquely* ergodic: there are no exceptional starting points at all, a
    stronger statement than Birkhoff's "almost every". Make $\alpha$ rational and
    ergodicity fails completely: the orbit is $q$ points, repeated for ever.

    Compare three samplers of the interval, all with the same true mean of $\tfrac12$:

    * the **rotation** by $(\sqrt5 - 1)/2$ — ergodic, not mixing, not chaotic;
    * the **logistic map at $r = 4$** — chaotic and mixing, with $\lambda = \ln 2$ and
      the exactly known invariant density $p(x) = 1/\pi\sqrt{x(1-x)}$, the arcsine law;
    * an **i.i.d. random sample** — the Monte Carlo baseline.
    """
    )
    return


@app.cell(hide_code=True)
def s3_fig(
    ARCSINE_DENSITY,
    ARCSINE_EDGES,
    ARCSINE_GRID,
    ARCSINE_MEASURED,
    C_BG,
    C_MEAN,
    C_PERT,
    C_TRUTH,
    DISC_LOGISTIC,
    DISC_RANDOM,
    DISC_ROTATION,
    ERR_LOGISTIC,
    ERR_RANDOM,
    ERR_ROTATION,
    SAMPLE_SIZES,
    finish_mpl,
    mpl_panels,
    np,
):
    _fig, _ax = mpl_panels(
        3,
        titles=(
            "error of the mean",
            "star discrepancy",
            "the logistic map's exact measure",
        ),
        height=3.5,
    )
    _n = np.asarray(SAMPLE_SIZES)
    _series = (
        ("rotation", ERR_ROTATION, DISC_ROTATION, C_TRUTH),
        ("logistic ($r=4$)", ERR_LOGISTIC, DISC_LOGISTIC, C_PERT),
        ("i.i.d. random", ERR_RANDOM, DISC_RANDOM, C_BG),
    )
    for _label, _err, _disc, _colour in _series:
        _ax[0].loglog(_n, np.asarray(_err), "o-", color=_colour, markersize=3.5,
                      linewidth=1.4, label=_label)
        _ax[1].loglog(_n, np.asarray(_disc), "o-", color=_colour, markersize=3.5,
                      linewidth=1.4, label=_label)
    _ref = _n.astype(float) ** -0.5
    for _axis, _anchor in ((_ax[0], ERR_RANDOM), (_ax[1], DISC_RANDOM)):
        _axis.loglog(_n, _ref * np.asarray(_anchor)[0] / _ref[0], ":",
                     color="#9a93b5", linewidth=1.0)
        _axis.set_xlabel("sample size $N$")
    _ax[0].set_ylabel(r"rms $|\bar A_N - 1/2|$")
    _ax[1].set_ylabel(r"$D_N^*$")
    _ax[0].legend(fontsize=7, frameon=False, loc="lower left")
    _ax[0].annotate(r"dotted: $N^{-1/2}$", xy=(0.97, 0.95), xycoords="axes fraction",
                    fontsize=7, color="#6b6580", ha="right", va="top")

    _edges = np.asarray(ARCSINE_EDGES)
    _centre = 0.5 * (_edges[1:] + _edges[:-1])
    _ax[2].step(_centre, np.asarray(ARCSINE_MEASURED), where="mid", color=C_PERT,
                linewidth=1.5, label="measured orbit")
    _ax[2].plot(np.asarray(ARCSINE_GRID), np.asarray(ARCSINE_DENSITY), color=C_MEAN,
                linewidth=1.8, linestyle="--",
                label=r"$1/\pi\sqrt{x(1-x)}$, exact")
    _ax[2].set_ylim(0.0, 4.0)
    _ax[2].set_xlabel("$x$")
    _ax[2].set_ylabel("density")
    _ax[2].legend(fontsize=7, frameon=False, loc="upper center")

    finish_mpl(
        _fig,
        "Ergodic without being chaotic — and the chaotic sampler only matches chance",
    )
    return


@app.cell(hide_code=True)
def s3_note(
    ERR_LOGISTIC,
    ERR_RANDOM,
    ERR_ROTATION,
    EXP_LOGISTIC,
    EXP_RANDOM,
    EXP_ROTATION,
    MEAN_LOGISTIC,
    REALISATIONS,
    SAMPLE_SIZES,
    VAR_LOGISTIC,
    W1_LOGISTIC,
    mo,
    np,
):
    def _sci(value, digits=1):
        """Render a float as LaTeX scientific notation, not Python's `1.2e-04`."""
        _mantissa, _exponent = f"{value:.{digits}e}".split("e")
        return rf"{_mantissa}\times 10^{{{int(_exponent)}}}"

    _n = np.asarray(SAMPLE_SIZES)
    _at = int(np.argmin(np.abs(_n - 1000)))
    _rot = np.asarray(ERR_ROTATION)[_at]
    _log = np.asarray(ERR_LOGISTIC)[_at]
    _rand = np.asarray(ERR_RANDOM)[_at]
    mo.md(
        rf"""
    | sampler | rms error at $N = {_n[_at]:,.0f}$ | measured scaling |
    |---|---|---|
    | rotation | ${_sci(_rot)}$ | $N^{{{EXP_ROTATION:.2f}}}$ |
    | logistic map, $r=4$ | ${_sci(_log)}$ | $N^{{{EXP_LOGISTIC:.2f}}}$ |
    | i.i.d. random | ${_sci(_rand)}$ | $N^{{{EXP_RANDOM:.2f}}}$ |

    *(rms over {REALISATIONS:.0f} realisations with different starting points)*

    **The chaotic sampler is indistinguishable from the random one.** Both scale as
    $N^{{-1/2}}$ and their errors at $N = {_n[_at]:,.0f}$ differ by
    {abs(_log / _rand - 1.0) * 100:.0f} %. Mixing buys exactly one thing — successive
    states that are effectively independent — and independence is the Monte Carlo rate,
    no better.

    **The rotation beats both by a factor of {_rand / _rot:.0f}**, scaling as
    $N^{{{EXP_ROTATION:.2f}}}$: the $\log N / N$ of a quasi-random sequence. Its orbit is
    *deliberately* uniform rather than independently uniform, and deliberate is better.
    This is quasi-Monte Carlo, arrived at from the dynamics rather than the numerics.

    The climate reading is direct. **A quasi-periodic component of the system — the
    seasonal cycle, the diurnal cycle, a steadily precessing orbital parameter — is
    cheap to average over. The chaotic part is not, and no amount of chaos makes it
    cheaper.** A model integration that samples fifty seasonal cycles has fifty good
    samples of the seasonal cycle and rather fewer than fifty of anything eddy-driven.

    **A check on the middle row, because it is easy to get wrong.** Floating-point orbits
    of the logistic map at $r = 4$ lose all their digits to roundoff within about fifty
    iterates, so a sceptic is right to ask whether these orbits sample anything at all.
    They do: the empirical measure of the computed orbit sits $W_1 = {W1_LOGISTIC:.4f}$
    from an exact draw from the arcsine law, with mean {MEAN_LOGISTIC:.5f} against an
    exact $1/2$ and variance {VAR_LOGISTIC:.5f} against an exact $1/8$. Individual
    trajectories are fiction; their statistics are not.

    *(Discrepancy is defined against a target measure, so the logistic orbit is pushed
    through its own distribution function first — it is uniform exactly when the orbit
    samples the arcsine law correctly. Measuring its raw discrepancy against the uniform
    measure instead reports a constant near 0.2 and says nothing about convergence.)*
    """
    )
    return


# ===========================================================================
# Section 4
# ===========================================================================
@app.cell(hide_code=True)
def s4_md(mo):
    mo.md(
        r"""
    ## 4 · One long run, or many short ones?

    Now the practical question. A centre has a fixed integration budget — say 2,000 time
    units of model time — and wants the best estimate of the model's climate. It can
    spend it on one run of 2,000, or fifty runs of 40, or anything between. Parallel
    machines make the second attractive; ensembles are how everything else in this book
    is done.

    For an ergodic system the answer is unambiguous, and it follows from the formula in
    section 2 with one addition: **every run must discard a spin-up**, and $M$ runs
    discard it $M$ times. With budget $C$ and spin-up $T_s$ the usable record is
    $C - M T_s$, so

    $$
    \operatorname{var}(\bar A) = \frac{\tau_{\rm int}\operatorname{var}(A)}{C - M T_s},
    $$

    which **rises monotonically with $M$**. The optimum is one long run and the penalty
    is exactly the spin-up, paid over and over. Note what the formula does *not* contain:
    the ensemble buys no accuracy of its own, because a state reached by integrating and
    a state reached by scattering are samples of the same measure — that was section 1.
    """
    )
    return


@app.cell(hide_code=True)
def s4_controls(mo):
    members = mo.ui.slider(
        start=1, stop=100, step=1, value=25, label="members $M$", show_value=True,
    )
    spin = mo.ui.slider(
        start=0.0, stop=100.0, step=5.0, value=20.0,
        label="spin-up discarded per run $T_s$ (TU)", show_value=True,
    )
    mo.md(f"""{members} &nbsp;&nbsp; {spin}""")
    return members, spin


@app.cell(hide_code=True)
def s4_fig(
    BUDGET,
    BUDGET_MEMBERS,
    BUDGET_PREDICTED,
    BUDGET_RATIO,
    C_MEAN,
    C_PERT,
    C_TRUTH,
    SPIN_COST,
    ergodic,
    finish_mpl,
    members,
    mpl_panels,
    np,
    spin,
):
    _fig, _ax = mpl_panels(
        2,
        titles=(
            "variance inflation from splitting the budget",
            "where the budget goes",
        ),
        height=3.6,
    )
    _m = np.asarray(BUDGET_MEMBERS)
    _fine = np.geomspace(1.0, 100.0, 200)

    _live = np.array([ergodic.budget_penalty(BUDGET, int(round(_k)), float(spin.value))
                      for _k in _fine])
    _ax[0].semilogx(_fine, _live, "--", color=C_MEAN, linewidth=1.5,
                    label=f"slider: $T_s = {spin.value:.0f}$")
    _ax[0].semilogx(_m, np.asarray(BUDGET_PREDICTED), "-", color=C_TRUTH,
                    linewidth=1.8, label=f"spin-up law ($T_s = {SPIN_COST:.0f}$)")
    _ax[0].semilogx(_m, np.asarray(BUDGET_RATIO), "o", color=C_PERT, markersize=7,
                    label="measured", zorder=5)
    _ax[0].axvline(members.value, color=C_MEAN, linewidth=1.0, linestyle=":")
    _ax[0].set_ylim(0.9, 4.0)
    _ax[0].set_xlabel("members $M$ (budget fixed)")
    _ax[0].set_ylabel("variance relative to one long run")
    _ax[0].legend(fontsize=7, frameon=False, loc="upper left")

    _labels = [f"{_k:.0f}" for _k in _m]
    _usable = BUDGET - _m * SPIN_COST
    _wasted = _m * SPIN_COST
    _ax[1].bar(_labels, _usable, color=C_TRUTH, label="usable record")
    _ax[1].bar(_labels, _wasted, bottom=_usable, color=C_PERT, alpha=0.75,
               label="discarded as spin-up")
    for _i, (_u, _w) in enumerate(zip(_usable, _wasted)):
        _ax[1].text(_i, _u * 0.5, f"{_u:,.0f}", ha="center", va="center",
                    fontsize=7, color="white", fontweight="bold")
    _ax[1].set_xlabel("members $M$")
    _ax[1].set_ylabel("time units")
    _ax[1].set_ylim(0.0, BUDGET * 1.18)
    _ax[1].legend(fontsize=7, frameon=False, loc="upper center", ncol=2)

    finish_mpl(_fig, "At fixed cost the ensemble buys nothing that the long run does not")
    return


@app.cell(hide_code=True)
def s4_note(
    BUDGET,
    BUDGET_EXCESS,
    BUDGET_MEMBERS,
    BUDGET_PREDICTED,
    BUDGET_RATIO,
    BUDGET_REPS,
    SPIN_COST,
    TAU_PLATEAU_X,
    TAU_SHORT_SEGMENT,
    ergodic,
    members,
    mo,
    np,
    spin,
):
    _m = np.asarray(BUDGET_MEMBERS)
    _ratio = np.asarray(BUDGET_RATIO)
    _pred = np.asarray(BUDGET_PREDICTED)
    _excess = np.asarray(BUDGET_EXCESS)
    _table = (chr(10) + "    ").join(
        f"| {_k:.0f} | {BUDGET / _k:,.0f} | {BUDGET - _k * SPIN_COST:,.0f} | "
        f"{_r:.3f} | {_p:.3f} | {_e:.3f} |"
        for _k, _r, _p, _e in zip(_m, _ratio, _pred, _excess)
    )
    _live = ergodic.budget_penalty(BUDGET, int(members.value), float(spin.value))
    _usable = BUDGET - members.value * spin.value
    mo.md(
        rf"""
    | $M$ | run length | usable | measured inflation | spin-up law | ratio |
    |---|---|---|---|---|---|
    {_table}

    *(each row is the variance of $\bar x$ over {BUDGET_REPS:.0f} independent
    repetitions of the whole experiment, at $C = {BUDGET:,.0f}$ and
    $T_s = {SPIN_COST:.0f}$)*

    **The spin-up accounting is the whole of the effect**, to within
    {100.0 * np.abs(_excess - 1.0).max():.0f} % at every member count. Splitting the
    budget fifty ways inflates the variance by {_ratio[-1]:.2f}, and the formula with no
    fitted constant predicts {_pred[-1]:.2f}. There is no separate penalty for short
    runs here because even the shortest segment — {BUDGET / _m[-1]:.0f} time units,
    {BUDGET / _m[-1] - SPIN_COST:.0f} of it usable — is long compared with
    $\tau_{{\rm int}} = {TAU_PLATEAU_X:.2f}$; measured on such a segment,
    $\tau_{{\rm eff}} = {TAU_SHORT_SEGMENT:.2f}$. Shorten it past the correlation time
    and a second penalty appears on top of this one.

    At the slider's setting — $M = {members.value}$, $T_s = {spin.value:.0f}$ — the
    usable record is {max(_usable, 0.0):,.0f} of {BUDGET:,.0f} time units and the
    variance is **{_live:.2f}×** that of one long run.

    **So why does anyone run ensembles?** Three reasons, none of which this experiment
    contradicts. Wall-clock time: fifty runs on fifty processors finish fifty times
    sooner, and the variance penalty of {_ratio[-1]:.2f} is a modest price for that.
    Initial-condition-dependent questions, which are *not* climatological averages at
    all — chapters 17 and 19. And the case where this section's conclusion **inverts
    completely**, which is next.
    """
    )
    return


# ===========================================================================
# Section 5
# ===========================================================================
@app.cell(hide_code=True)
def s5_md(mo):
    mo.md(
        r"""
    ## 5 · When the ergodic time exceeds the record

    Everything so far assumed the run was long compared with the time the system takes
    to explore its attractor. Ergodicity guarantees that time is finite. It does not
    guarantee it is *small*, and there is a large and physically important class of
    systems where it is neither.

    Take chapter 27's double well with additive noise,

    $$
    \mathrm{d}x = (x - x^3)\,\mathrm{d}t + \sigma\,\mathrm{d}W ,
    \qquad V(x) = -\tfrac12 x^2 + \tfrac14 x^4 ,
    $$

    the normal form for a system with two competing states — two circulation regimes,
    two ice-cover states, an overturning circulation with an on and an off branch. This
    system **is ergodic**: noise carries it over the barrier eventually, so there is no
    invariant subset and no exceptional starting point. Its invariant measure is known
    exactly,

    $$
    p(x) = Z^{-1}\exp\!\left(-\frac{2V(x)}{\sigma^2}\right),
    $$

    it is symmetric, and therefore $\langle x \rangle = 0$ exactly.

    The time it takes to *find* that measure is Kramers',
    $\tau \simeq 2\pi (V''_w |V''_s|)^{-1/2}\exp(2\Delta V/\sigma^2)$ — exponential in
    the barrier over the noise. Ergodicity is a statement about $T \to \infty$; this is
    the number that says whether your $T$ qualifies.
    """
    )
    return


@app.cell(hide_code=True)
def s5_fig(
    C_BG,
    C_MEAN,
    C_PERT,
    C_SAT,
    C_TRUTH,
    TAU_ERG,
    WELL_EDGES,
    WELL_EXACT,
    WELL_GRID,
    WELL_MEASURED,
    WELL_NAIVE,
    WELL_RMS,
    WELL_SHORT,
    WELL_WINDOWS,
    finish_mpl,
    mpl_panels,
    np,
):
    _fig, _ax = mpl_panels(
        3,
        titles=(
            "the measure, and one short run",
            "true error vs reported",
            "overconfidence",
        ),
        height=3.5,
    )

    _edges = np.asarray(WELL_EDGES)
    _centre = 0.5 * (_edges[1:] + _edges[:-1])
    _ax[0].plot(np.asarray(WELL_GRID), np.asarray(WELL_EXACT), color=C_MEAN,
                linewidth=2.0, label="exact Boltzmann")
    _ax[0].step(_centre, np.asarray(WELL_MEASURED), where="mid", color=C_TRUTH,
                linewidth=1.4, label="20,000 TU × 400")
    _ax[0].step(_centre, np.asarray(WELL_SHORT), where="mid", color=C_PERT,
                linewidth=1.4, linestyle="--", label="one run, 100 TU")
    _ax[0].set_xlabel("$x$")
    _ax[0].set_ylabel("density")
    _ax[0].legend(fontsize=7, frameon=False, loc="upper center")

    _w = np.asarray(WELL_WINDOWS)
    _ax[1].loglog(_w, np.asarray(WELL_RMS), "o-", color=C_PERT, markersize=4,
                  linewidth=1.6, label="true rms error")
    _ax[1].loglog(_w, np.asarray(WELL_NAIVE), "o--", color=C_BG, markersize=4,
                  linewidth=1.6, label="error bar the run reports")
    _ax[1].axvline(TAU_ERG, color=C_SAT, linewidth=1.2, linestyle=":")
    _ax[1].annotate(rf"$\tau_{{\rm erg}} \approx {TAU_ERG:.0f}$",
                    xy=(TAU_ERG * 1.2, np.asarray(WELL_NAIVE).min() * 1.1),
                    fontsize=7, color=C_SAT)
    _ax[1].set_xlabel("run length $T$ (time units)")
    _ax[1].set_ylabel(r"error in $\bar x$   (true value 0)")
    # centre-left is the one genuinely empty quadrant: the true-error curve
    # runs along the top and the reported one along the bottom
    _ax[1].legend(fontsize=7, frameon=False, loc="center left")

    _ratio = np.asarray(WELL_RMS) / np.asarray(WELL_NAIVE)
    _ax[2].semilogx(_w, _ratio, "o-", color=C_TRUTH, markersize=4, linewidth=1.6)
    _ax[2].axhline(1.0, color=C_MEAN, linewidth=1.2, linestyle="--")
    _ax[2].axvline(TAU_ERG, color=C_SAT, linewidth=1.2, linestyle=":")
    _ax[2].set_xlabel("run length $T$ (time units)")
    _ax[2].set_ylabel("true error ÷ reported error")
    _ax[2].annotate("honest", xy=(_w[0] * 1.1, 1.6), fontsize=7, color=C_MEAN)

    finish_mpl(_fig, "An ergodic system whose ergodic time nobody has")
    return


@app.cell(hide_code=True)
def s5_note(
    BARRIER,
    EXPONENT,
    GRAND_MEAN,
    NOISE,
    OCCUPANCY,
    TAU_ERG,
    TAU_KRAMERS,
    TAU_WITHIN,
    TYPICAL,
    WELL_NAIVE,
    WELL_OVERCONFIDENCE,
    WELL_RMS,
    WELL_WINDOWS,
    mo,
    np,
):
    _w = np.asarray(WELL_WINDOWS)
    _rms = np.asarray(WELL_RMS)
    _naive = np.asarray(WELL_NAIVE)
    _over = np.asarray(WELL_OVERCONFIDENCE)
    _table = (chr(10) + "    ").join(
        f"| {_t:,.0f} | {_t / TAU_ERG:.2f} | {_r:.3f} | {_n:.3f} | {_o:.0f}× |"
        for _t, _r, _n, _o in zip(_w, _rms, _naive, _over)
    )
    _at30 = int(np.argmin(np.abs(_w - 30.0)))
    mo.md(
        rf"""
    | $T$ (TU) | $T/\tau_{{\rm erg}}$ | true rms error | error bar the run reports | overconfidence |
    |---|---|---|---|---|
    {_table}

    **A run of {_w[_at30]:,.0f} time units gets the answer wrong by {_rms[_at30]:.2f}
    and says it is accurate to {_naive[_at30]:.3f}.** The true value is $0$. The run is
    {_over[_at30]:.0f} times more confident than it is entitled to be, and — this is the
    part that matters — **nothing inside the run gives that away**. It looks perfectly
    converged: the trajectory rattles around one well, its running mean settles quickly,
    its autocorrelation decays in {TAU_WITHIN:.1f} time units, and every standard
    convergence check is passed. The check measures the within-well wobble, which is
    genuinely fast. The quantity it is being used to certify is the occupancy of the two
    wells, which is genuinely slow.

    **Two timescales, and the diagnostic sees the wrong one.** Within-well
    decorrelation: {TAU_WITHIN:.1f} time units. Ergodic time, implied by the measured
    convergence: **{TAU_ERG:.0f}** time units, against Kramers'
    {TAU_KRAMERS:.0f} — {100.0 * abs(TAU_ERG / TAU_KRAMERS - 1.0):.0f} % apart, from
    a formula with no fitted constant, at $2\Delta V/\sigma^2 = {EXPONENT:.2f}$. The
    error bar is wrong by roughly the square root of their ratio.

    **The pooled ensemble, meanwhile, is right.** All 400 members together give
    $\bar x = {GRAND_MEAN:+.4f}$ against an exact $0$, and an occupancy of
    {OCCUPANCY:.4f} against an exact $\tfrac12$ — because the members were *started* in
    both wells. Section 4's conclusion inverts exactly here: when the ergodic time
    exceeds the run length, the ensemble is not a convenience, it is the only estimator
    that works, and the long run is not slow but **biased**.

    And the decision between them cannot be made from the run. It needs $\tau_{{\rm erg}}$,
    which is a property of a barrier the run may never have crossed.
    """
    )
    return


@app.cell(hide_code=True)
def s5_controls(mo):
    noise = mo.ui.slider(
        start=0.20, stop=0.70, step=0.01, value=0.35,
        label="noise amplitude $\\sigma$", show_value=True,
    )
    confidence = mo.ui.slider(
        start=1, stop=50, step=1, value=10,
        label="ergodic times required $T/\\tau_{\\rm erg}$", show_value=True,
    )
    mo.md(f"""{noise} &nbsp;&nbsp; {confidence}""")
    return confidence, noise


@app.cell(hide_code=True)
def s5_out(
    BARRIER,
    DAYS_PER_TU,
    NOISE,
    TAU_ERG,
    TAU_KRAMERS,
    confidence,
    earlywarning,
    mo,
    noise,
):
    _sigma = float(noise.value)
    _tau = earlywarning.kramers_escape_time(BARRIER, _sigma, 2.0, 1.0)
    _calibration = TAU_ERG / TAU_KRAMERS
    _needed = confidence.value * _tau * _calibration
    _half = earlywarning.kramers_escape_time(BARRIER, 0.5 * _sigma, 2.0, 1.0)
    _triple = earlywarning.kramers_escape_time(3.0 * BARRIER, _sigma, 2.0, 1.0)
    _sixfold = earlywarning.kramers_escape_time(6.0 * BARRIER, _sigma, 2.0, 1.0)
    _six_mantissa, _six_exponent = f"{_sixfold * DAYS_PER_TU / 365.0:.1e}".split("e")
    _six_exponent = str(int(_six_exponent))
    mo.md(
        rf"""
    At $\sigma = {_sigma:.2f}$ the barrier is $2\Delta V/\sigma^2 =
    {2.0 * BARRIER / _sigma**2:.2f}$ and Kramers gives $\tau = {_tau:,.0f}$ time units.
    Scaling by the calibration measured above ({_calibration:.2f}), a record of
    {confidence.value} ergodic times is **{_needed:,.0f} time units** —
    {_needed * DAYS_PER_TU / 365.0:,.0f} years at five days per unit.

    **Halve the noise and that becomes {_half * confidence.value * _calibration:,.0f}**
    — a factor of {_half / _tau:,.0f}. The requirement is exponential in
    $\Delta V/\sigma^2$, so it is the one quantity in this book that a faster computer
    does not fix. A barrier three times this one at the same noise needs
    {_triple * DAYS_PER_TU / 365.0:,.0f} years of model time, and six times needs
    ${_six_mantissa}\times 10^{{{_six_exponent}}}$ years — over half the age of the
    Earth. Both systems are still, formally, ergodic.
    """
    )
    return


# ===========================================================================
# Section 6
# ===========================================================================
@app.cell(hide_code=True)
def s6_md(mo):
    mo.md(
        r"""
    ## 6 · No invariant measure at all

    Sections 1 to 5 assumed there was an invariant measure to estimate. Under a trend
    there is not.

    An invariant measure is defined by being unchanged by the dynamics. If the forcing
    is a function of time, the dynamics is different at every instant and no distribution
    is left unchanged by it. The object that replaces $\nu$ is a *time-dependent* measure
    $\nu_t$ — the **snapshot** or **pullback** attractor: the distribution at time $t$ of
    an ensemble launched in the indefinite past. It is a perfectly good object, and it
    has one estimator, not two.

    Ramp Lorenz 63's Rayleigh number from $\rho = 28$ to $40$ over 4,000 time units and
    ask for $\langle z\rangle$ as it goes. The ensemble mean across members is an
    estimate of $\nu_t$. A trailing time average along one member is an estimate of
    nothing in particular — and it fails in a specific, predictable way.

    For a mean that drifts linearly at rate $b$, a trailing average over a window $T$
    returns the value the mean had at the window's **midpoint**:

    $$
    \frac{1}{T}\int_{t-T}^{t}(a + bs)\,\mathrm{d}s = a + bt - \frac{bT}{2}.
    $$

    The bias is $-bT/2$, exactly, independent of the variability about the mean. It does
    not shrink with a longer record. **Lengthening the window makes it worse**, at the
    same time as it reduces the sampling noise — which is what makes the failure so
    hard to see in practice.
    """
    )
    return


@app.cell(hide_code=True)
def s6_fig(
    C_MEAN,
    C_PERT,
    C_SPREAD,
    C_TRUTH,
    RAMP_ENS_MEAN,
    RAMP_LAG,
    RAMP_PREDICTED,
    RAMP_TIME,
    RAMP_TRAIL_100,
    RAMP_TRAIL_400,
    RAMP_WINDOWS,
    finish_mpl,
    mpl_panels,
    np,
):
    _fig, _ax = mpl_panels(
        3,
        titles=(
            r"$\langle z \rangle$ under a ramp",
            "the trailing mean, minus the ensemble",
            r"the lag, against $-bT/2$",
        ),
        height=3.5,
    )
    _t = np.asarray(RAMP_TIME)
    _ens = np.asarray(RAMP_ENS_MEAN)
    _t100 = np.asarray(RAMP_TRAIL_100)
    _t400 = np.asarray(RAMP_TRAIL_400)

    _ax[0].plot(_t, _ens, color=C_TRUTH, linewidth=2.0,
                label="ensemble mean (200 members)")
    _ax[0].plot(_t, _t100, color=C_MEAN, linewidth=1.4,
                label="trailing mean, $T = 100$")
    _ax[0].plot(_t, _t400, color=C_PERT, linewidth=1.4,
                label="trailing mean, $T = 400$")
    _ax[0].set_xlabel("time (time units)")
    _ax[0].set_ylabel("$z$")
    _ax[0].legend(fontsize=7, frameon=False, loc="upper left")

    # the lag is 0.6 against a signal that moves by 12: invisible above, so it
    # gets its own panel rather than an assurance that it is there
    _w = np.asarray(RAMP_WINDOWS)
    _pred = np.asarray(RAMP_PREDICTED)
    _keep = _t > 1000.0
    for _curve, _colour, _label, _level in (
        (_t100, C_MEAN, "$T = 100$", _pred[np.argmin(np.abs(_w - 100.0))]),
        (_t400, C_PERT, "$T = 400$", _pred[np.argmin(np.abs(_w - 400.0))]),
    ):
        _difference = (_curve - _ens)[_keep]
        _ax[1].plot(_t[_keep], _difference, color=_colour, linewidth=0.6, alpha=0.30)
        _ax[1].axhline(float(np.nanmean(_difference)), color=_colour, linewidth=2.0,
                       label=f"{_label}, measured")
        _ax[1].axhline(_level, color=_colour, linewidth=1.4, linestyle="--")
    _ax[1].axhline(0.0, color=C_SPREAD, linewidth=0.9)
    _ax[1].set_xlabel("time (time units)")
    _ax[1].set_ylabel(r"$\bar z_T - $ ensemble mean")
    _ax[1].set_ylim(-2.2, 1.6)
    _ax[1].legend(fontsize=7, frameon=False, loc="upper right", ncol=2)
    # the scatter is not the trailing average's error -- it is the 200-member
    # ensemble mean's own sampling noise, which is larger
    _ax[1].annotate("dashed: $-bT/2$, predicted\nscatter: the ensemble's own noise, $\\pm0.74$",
                    xy=(0.03, 0.04), xycoords="axes fraction", fontsize=6.5,
                    color="#6b6580")

    _ax[2].plot(_w, -np.asarray(RAMP_LAG), "o", color=C_PERT, markersize=7,
                label="measured", zorder=5)
    _fine = np.linspace(0.0, _w.max() * 1.05, 60)
    _slope = -_pred[-1] / _w[-1]
    _ax[2].plot(_fine, _slope * _fine, "-", color=C_TRUTH, linewidth=1.6,
                label=r"$bT/2$, exact")
    _ax[2].set_xlabel("averaging window $T$ (time units)")
    _ax[2].set_ylabel(r"lag in $\langle z\rangle$")
    _ax[2].legend(fontsize=7, frameon=False, loc="upper left")

    finish_mpl(_fig, "Under a trend the time average is not slow — it is inconsistent")
    return


@app.cell(hide_code=True)
def s6_controls(mo):
    window = mo.ui.slider(
        start=25.0, stop=1000.0, step=25.0, value=400.0,
        label="averaging window $T$ (time units)", show_value=True,
    )
    mo.md(f"""{window}""")
    return (window,)


@app.cell(hide_code=True)
def s6_note(
    DAYS_PER_TU,
    RAMP_DRIFT,
    RAMP_ENS_EARLY,
    RAMP_ENS_LATE,
    RAMP_ENS_SPREAD,
    RAMP_ENS_STDERR,
    RAMP_FIT_EARLY,
    RAMP_FIT_LATE,
    RAMP_LAG,
    RAMP_MEMBERS,
    RAMP_PREDICTED,
    RAMP_RATE,
    RAMP_WINDOWS,
    TAU_PLATEAU_Z,
    VAR_Z,
    ergodic,
    mo,
    np,
    window,
):
    _w = np.asarray(RAMP_WINDOWS)
    _lag = np.asarray(RAMP_LAG)
    _pred = np.asarray(RAMP_PREDICTED)
    _table = (chr(10) + "    ").join(
        f"| {_t:,.0f} | ${_l:+.4f}$ | ${_p:+.4f}$ | {100.0 * abs(_l / _p - 1.0):.0f} % |"
        for _t, _l, _p in zip(_w, _lag, _pred)
    )
    _live_bias = ergodic.trailing_average_bias(RAMP_DRIFT, float(window.value))
    _live_noise = ergodic.sampling_error(VAR_Z, TAU_PLATEAU_Z, float(window.value))
    _live_total = float(np.hypot(_live_bias, _live_noise))
    _best_window = float((2.0 * TAU_PLATEAU_Z * VAR_Z / RAMP_DRIFT**2) ** (1.0 / 3.0))
    _best_bias = abs(ergodic.trailing_average_bias(RAMP_DRIFT, _best_window))
    _best_noise = ergodic.sampling_error(VAR_Z, TAU_PLATEAU_Z, _best_window)
    _best_total = float(np.hypot(_best_bias, _best_noise))
    _members_to_match = (RAMP_ENS_SPREAD / _best_total) ** 2
    mo.md(
        rf"""
    | window $T$ | measured lag | $-bT/2$ | apart |
    |---|---|---|---|
    {_table}

    The drift is $b = {RAMP_DRIFT:.5f}$ per time unit — the ramp rate
    {RAMP_RATE:.4f} times the measured $\mathrm{{d}}\langle z\rangle/\mathrm{{d}}\rho$ of
    the stationary attractor, with nothing fitted to the ramped run at all. The ensemble
    mean tracks the stationary climatology throughout, {RAMP_ENS_EARLY:.2f} against
    {RAMP_FIT_EARLY:.2f} early and {RAMP_ENS_LATE:.2f} against {RAMP_FIT_LATE:.2f} late,
    which is what licenses reading the ramp as a sequence of climates.

    **At $T = {window.value:.0f}$ the trailing average is low by
    {abs(_live_bias):.3f}** — it is reporting the climate of
    {window.value / 2.0:.0f} time units ({window.value * DAYS_PER_TU / (2 * 365):.1f}
    years) ago, and calling it today's.

    **The bias does not trade against the record length; it trades against the noise.**
    Lengthening the window cuts the sampling error as $T^{{-1/2}}$ and grows the bias as
    $T$, so there is an optimum and the total error at it does not go to zero:

    $$
    T^\star = \left(\frac{{2\tau\operatorname{{var}}(A)}}{{b^2}}\right)^{{1/3}},
    \qquad
    \text{{rms error}} \propto b^{{2/3}} .
    $$

    For this ramp $T^\star = {_best_window:.0f}$ time units, where the bias is
    {_best_bias:.3f} and the noise {_best_noise:.3f} for a total of
    **{_best_total:.3f}** — and *that is the floor*. No longer run, no finer output
    interval and no faster computer lowers it, because it is set by $b$. At the slider's
    {window.value:.0f} the same decomposition gives {abs(_live_bias):.3f} bias and
    {_live_noise:.3f} noise, {_live_total:.3f} in total.

    **The ensemble has no floor.** Its error is
    ${RAMP_ENS_SPREAD:.2f}/\sqrt{{M}}$ — $\pm{RAMP_ENS_STDERR:.3f}$ at
    {RAMP_MEMBERS:.0f} members — with no bias at all, so it falls as $M^{{-1/2}}$
    for ever. Matching the trailing average's floor takes
    {_members_to_match:,.0f} members here, which is *more* integration than the trailing
    average uses: under a **slow** trend the time average is both adequate and cheaper,
    and section 4 still applies. What changes is that its error stops falling.

    Triple the trend and the floor roughly doubles, while the ensemble's does not move.
    **This is the structural reason climate projection is done with ensembles**, and it
    is not the reason usually given. The usual one is that an ensemble samples internal
    variability. The stronger one is that under a trend a time average is estimating a
    quantity that does not exist, and the resulting bias is invisible from inside the
    estimate: more data along the trajectory makes the error bar smaller and leaves the
    bias exactly where it was.
    Chapter 28 measured the same failure in the language of forecast skill; here it is in
    the language of the measure.
    """
    )
    return


# ===========================================================================
# Section 7
# ===========================================================================
@app.cell(hide_code=True)
def s7_md(
    BOX_DIMENSION,
    D_KY,
    TAU_ERG,
    TAU_INT_Z,
    TAU_PLATEAU_Z,
    TAU_WITHIN,
    W1_GAUSSIAN,
    W1_Z,
    mo,
):
    mo.md(
        rf"""
    ## 7 · What this chapter establishes

    1. **Climate is an invariant measure; a run is a sample of it.** A long run and a
       scattered ensemble estimate the same object and agree to
       $W_1 = {W1_Z:.3f}$, against {W1_GAUSSIAN:.2f} for a Gaussian with the same mean
       and variance. Neither is more "the climate" than the other.

    2. **That measure has no density.** It lives on a set of dimension
       {BOX_DIMENSION:.2f} (box counting, biased low) or $D_{{KY}} = {D_KY:.2f}$ (from
       the spectrum) inside a three-dimensional space, so it assigns probability one to a
       set of zero volume. Every climatological PDF is a coarse-graining, and the
       coarse-graining is a choice.

    3. **Birkhoff gives no rate, and the rate depends on the observable.** Three
       quantities of the same trajectory needed run lengths differing by a factor of
       ninety for the same accuracy. The exact moment identities explain why, and they
       double as a convergence diagnostic requiring no reference run.

    4. **The standard error bar can be wrong in either direction.** The
       initial-positive-sequence rule overstates the uncertainty of $\langle z\rangle$
       by {(TAU_INT_Z / TAU_PLATEAU_Z) ** 0.5:.0f}-fold, because it discards the
       negative lobes of an oscillating autocorrelation; and it *understates* a bistable
       system's by fifteen-fold, because it measures the fast timescale
       ({TAU_WITHIN:.1f} time units) when the answer is governed by the slow one
       ({TAU_ERG:.0f}).

    5. **Ergodicity is not chaos, and chaos is the worse sampler.** A zero-exponent
       rotation averages a thousand times more accurately than a chaotic map at the same
       sample size. Mixing buys independence, and independence is only $N^{{-1/2}}$.

    6. **At fixed cost, one long run beats an ensemble — until it doesn't.** The penalty
       for splitting is exactly the spin-up, paid $M$ times. But when the ergodic time
       exceeds the run length the conclusion inverts: the long run is biased and only the
       ensemble is right, and nothing inside the long run reveals which regime it is in.

    7. **Under a trend there is no invariant measure at all.** The trailing average is
       not slow but inconsistent, biased by $-bT/2$ whatever the record length, while
       the ensemble's error shrinks with members. That is the structural argument for
       ensembles in climate projection.

    ---

    **Where this sits in the book.** Every earlier chapter that averaged something — the
    saturation level in chapter 9, the climatology in chapter 22, the epoch means in
    chapter 28 — was using this chapter's theorem, and each of them had to decide how
    long a run to average over. The answers they used are defensible for the reason
    section 2 gives, and none of them would have been defensible for
    $\langle x \rangle$.

    Part VIII is terminal: nothing depends on it. The one operational thing to carry out
    of it is **the diagnostic**. A control run can be interrogated about its own
    convergence, with no reference run, by testing an identity the invariant measure
    must satisfy. Lorenz 63 has four. Realistic models have their own — global mass,
    energy at top of atmosphere, the Sverdrup balance — and the residual in each is a
    measurement of how far the run is from its own climate.
    """
    )
    return


@app.cell(hide_code=True)
def s7_exercises(mo):
    mo.md(
        r"""
    ## Exercises

    **Analytic.**

    1. Show that $\overline{xy}_T - \overline{x^2}_T = (x_T^2 - x_0^2)/2\sigma T$ holds
       for *any* trajectory of Lorenz 63, chaotic or not, and hence that it is a test of
       the integrator rather than of ergodicity. Then find the analogous identity for
       Lorenz 96 and say what it would diagnose.

    2. A trailing average of window $T$ has bias $-bT/2$ and sampling error
       $\sqrt{\tau\operatorname{var}(A)/T}$. Minimise the total mean square error over
       $T$, and show that the optimum window scales as $b^{-2/3}$. Evaluate it for
       section 6's ramp and compare with the windows in the table.

    3. The rotation's averages converge like $\log N/N$ for a badly approximable
       $\alpha$. Show that for $\alpha$ with an unusually good rational approximation
       $p/q$ the error is $O(1)$ for all $N < q$, and say what that implies about
       averaging over a near-resonant orbital cycle.

    **Computational.**

    4. Reproduce section 2's $\tau_{\rm eff}(T)$ curves for $\langle xz \rangle$ and
       $\langle y^2\rangle$. Predict from the identities which will converge fast, then
       check.

    5. Section 5's calibration between the measured ergodic time and Kramers' formula was
       {6 %} at one noise amplitude. Measure it across the noise ladder and say over what
       range of $2\Delta V/\sigma^2$ the formula is usable as more than a scaling.

    6. Build the 2 × 2 of section 4 and section 5: budget split $M$ ways against barrier
       height, and find the barrier at which the optimal $M$ jumps from 1 to "as many as
       possible". Is the transition sharp?

    **Exploratory.**

    7. Lorenz 63 at $\rho = 28$ has one attractor. At $\rho = 24.2$ it has three
       coexisting ones. Estimate how long a noiseless run must be to discover that its
       climatology depends on where it started — and then argue about whether a coupled
       model's control run could contain the same failure undetected.
    """
    )
    return


